 components.append({'source_id':f['source_id'],'original_problem':q[':question/problem'],'original_solution':q.get(':question/worked-solution'),'difficulty':q.get(':question/difficulty'),'template':r['generation']['template'],'profile':r['generation']['profile'],'original_parameters':r['generation']['parameters'],'field_layout':[{'key':field[':answer-field/key'],'type':v.enum(field[':answer-field/type']),'choice_count':len(choices),'supplied_answer_fragment':'none: every answer is a complete interval membership statement or complete compound inequality'}],'choices':choices,'ordered_operative_stages':[] if ':question/worked-solution'not in q else ['parenthesis/bracket convention','display given finite half-open object','left endpoint inclusion and requested notation symbol','right endpoint inclusion and requested notation symbol','display complete translated result']})
